import test from 'node:test';
import assert from 'node:assert/strict';
import {correctProductData} from './product-title-corrections.mjs';
const rows=[{id:'8RopqzkV8UyasWEZxMB8',titulo:'Perfume Lattafa Asad 100ml Eau De Parfum Original Árabe Original Com Nota Fiscal E Selo Original Lataffa',listing:'MLB3998743869'},{id:'96Pf23TdUYjzKH9stEXS',titulo:'Mini Aspirador De Pó Portátil Recarregável Chrome Technology Soprador Usb Automotivo 3em1 Sem Fio Premium Vácuo Limpeza Carro Multifuncional Casa',listing:'MLB6433211634'}];
test('triagem60 protege identidade operação e idempotência',()=>{for(const r of rows){const p={...r,preco:'salvo',historico:'preservado',linkAfiliado:'https://meli.la/preservar',variation_id:'123'},x=correctProductData(p);for(const k of Object.keys(p).filter(k=>k!=='titulo'))assert.deepEqual(x[k],p[k]);assert.deepEqual(correctProductData(x),x);for(const alt of [{id:'outro'},{titulo:'Capa para '+r.titulo},{link:'https://www.mercadolivre.com.br/p/MLB12345678?wid=MLB9999999999'}])assert.equal(correctProductData({...p,comentario:'preservar',...alt}).comentario,'preservar');assert.ok(x.titulo.length<=100);}});
test('Asad não certifica autenticidade ou desempenho e não transfere Zanzibar',()=>{const x=correctProductData(rows[0]);assert.equal(x.titulo,'Perfume Lattafa Asad Eau de Parfum 100 ml');assert.match(x.comentario,/não representam autenticação/);assert.match(x.comentario,/não garantem rendimento/);assert.match(x.comentario,/sem confundi-lo com Asad Zanzibar/);assert.doesNotMatch(x.pros,/original|excelente|fixação|horas/i);});
test('mini aspirador não inventa a terceira função nem mede sucção por watts',()=>{const x=correctProductData(rows[1]);assert.match(x.comentario,/confirme a terceira função/);assert.match(x.comentario,/não é um resultado de teste de sucção/);assert.match(x.comentario,/Não presumimos uso com líquidos/);assert.doesNotMatch(x.pros,/lavável|\bPa\b|minutos|50 W|profissional/i);});
test('Galaxy A17 não recebe revisão ou variante por aproximação',()=>{const p={id:'8sDa6bmYd25zEEKRnQJn',titulo:'Celular Samsung Galaxy A17',comentario:'Descrição anterior atribuída ao vendedor',comparison:null},x=correctProductData(p);for(const key of Object.keys(p))assert.deepEqual(x[key],p[key]);});
